def countPatternCuts(seq, patterns):
    M = 1000000007
    pats = set(tuple(q) for q in patterns)
    lens = sorted(set(len(q) for q in patterns))
    n = len(seq)
    ways = [0] * (n + 1)
    ways[0] = 1
    for i in range(1, n + 1):
        total = 0
        for L in lens:
            if L > i:
                break
            if ways[i - L] and tuple(seq[i - L:i]) in pats:
                total += ways[i - L]
        ways[i] = total % M
    return ways[n]
